using System;
using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "LuminaryBookmarkOmenData", menuName = "Data/Battle/Omens System/Omen Data/Moonie/LuminaryBookmarkOmenData")]
public class LuminaryBookmarkOmenData : ConvertOmenData
{
	protected override Action<List<DiceInstance>> InitializeOmenAction(OmenInstance omenInstance)
	{
		return delegate(List<DiceInstance> diceInstances)
		{
			for (int i = 0; i < diceInstances.Count; i++)
			{
				if (diceInstances[i].DiceOwnerEnum == DiceOwnerEnum.ENEMY)
				{
					diceInstances[i].ActionOwner.GetComponent<CorruptionStats>().Purify(ActionValue, null);
					omenInstance.EnqueueOmenFeedbackAndPlay();
				}
			}
		};
	}
}
